mkdir -p /app/output && cat > /app/output/index.html <<'HTML'
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Fresh Pantry — Discover Everyday Deliciousness</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Nunito:wght@600;700;800&family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
  <style>
    :root {
      --green: #2D6A4F;
      --green-700: #1f513b;
      --orange: #F4A261;
      --cream: #FEFAE0;
      --sunny: #FFD166;
      --terracotta: #E07A5F;
      --ink: #1f2937;
      --muted: #5b6472;
      --card: #ffffff;
      --shadow: 0 10px 28px rgba(26, 44, 34, 0.10);
      --radius-lg: 22px;
      --radius-md: 16px;
      --radius-sm: 12px;
    }

    * { box-sizing: border-box; }
    html, body { margin: 0; padding: 0; }
    body {
      font-family: 'Inter', system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
      color: var(--ink);
      background: linear-gradient(180deg, #fffef6 0%, var(--cream) 100%);
      line-height: 1.55;
    }

    h1, h2, h3, h4 {
      font-family: 'Nunito', 'Inter', sans-serif;
      margin: 0;
      line-height: 1.15;
      letter-spacing: 0.2px;
    }

    .container {
      width: min(1120px, calc(100% - 2.2rem));
      margin-inline: auto;
    }

    .section { padding: 72px 0; }

    .header {
      position: sticky;
      top: 0;
      z-index: 30;
      backdrop-filter: blur(10px);
      background: rgba(254, 250, 224, 0.9);
      border-bottom: 1px solid rgba(45, 106, 79, 0.15);
    }

    .header-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      min-height: 76px;
      gap: 1rem;
    }

    .brand {
      display: flex;
      align-items: center;
      gap: 10px;
      font-family: 'Nunito', sans-serif;
      font-weight: 800;
      font-size: 1.24rem;
      color: var(--green);
      text-decoration: none;
      white-space: nowrap;
    }

    .brand-badge {
      width: 32px;
      height: 32px;
      border-radius: 10px;
      background: linear-gradient(145deg, var(--green) 0%, #3f8b67 100%);
      color: #fff;
      display: grid;
      place-items: center;
      font-size: 1.1rem;
      box-shadow: 0 6px 16px rgba(45, 106, 79, 0.35);
    }

    .nav {
      display: flex;
      align-items: center;
      gap: .3rem;
      flex-wrap: wrap;
      justify-content: flex-end;
    }

    .nav a {
      color: var(--green-700);
      text-decoration: none;
      font-weight: 700;
      padding: .55rem .8rem;
      border-radius: 999px;
      transition: background .2s ease, transform .2s ease;
    }

    .nav a:hover,
    .nav a:focus-visible {
      background: rgba(45, 106, 79, 0.11);
      outline: none;
      transform: translateY(-1px);
    }

    .hero {
      padding: 64px 0 38px;
    }

    .hero-grid {
      display: grid;
      grid-template-columns: 1.1fr .9fr;
      gap: 28px;
      align-items: center;
    }

    .eyebrow {
      display: inline-block;
      padding: .4rem .75rem;
      border-radius: 999px;
      background: #e5f3eb;
      color: var(--green);
      font-weight: 700;
      margin-bottom: 14px;
      font-size: .95rem;
    }

    .hero h1 {
      font-size: clamp(2.05rem, 5vw, 3.4rem);
      color: var(--green-700);
      margin-bottom: 14px;
    }

    .hero p {
      margin: 0 0 26px;
      color: var(--muted);
      max-width: 58ch;
      font-size: 1.06rem;
    }

    .hero-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 12px;
    }

    .btn {
      border: none;
      border-radius: 999px;
      padding: 13px 20px;
      font-weight: 700;
      font-size: .98rem;
      cursor: pointer;
      transition: transform .2s ease, box-shadow .2s ease, background .2s ease;
      min-height: 46px;
    }

    .btn-primary {
      background: var(--green);
      color: #fff;
      box-shadow: 0 10px 20px rgba(45, 106, 79, .28);
    }

    .btn-secondary {
      background: #fff;
      color: var(--green-700);
      border: 1px solid rgba(45, 106, 79, 0.25);
    }

    .btn:hover,
    .btn:focus-visible {
      transform: translateY(-2px);
      outline: none;
    }

    .hero-media {
      position: relative;
      border-radius: var(--radius-lg);
      overflow: hidden;
      min-height: 330px;
      box-shadow: var(--shadow);
      background: #ddd;
    }

    .hero-media img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      display: block;
    }

    .hero-chip {
      position: absolute;
      right: 14px;
      bottom: 14px;
      background: rgba(255,255,255,0.94);
      border-radius: 999px;
      padding: .5rem .85rem;
      font-size: .9rem;
      font-weight: 700;
      color: var(--green-700);
    }

    .stats-banner {
      background: linear-gradient(130deg, var(--green) 0%, #3f8b67 55%, #6ab087 100%);
      color: #fff;
      border-radius: var(--radius-lg);
      padding: 28px 24px;
      box-shadow: var(--shadow);
    }

    .stats-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 14px;
    }

    .stat {
      text-align: center;
      padding: 8px;
    }

    .stat strong {
      display: block;
      font-family: 'Nunito', sans-serif;
      font-size: clamp(1.45rem, 3.1vw, 2rem);
      margin-bottom: 2px;
    }

    .stat span {
      font-size: .92rem;
      opacity: .95;
    }

    .section-head {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 1rem;
      margin-bottom: 22px;
    }

    .section-head h2 { font-size: clamp(1.55rem, 3.4vw, 2.2rem); color: var(--green-700); }
    .section-head p { margin: 8px 0 0; color: var(--muted); }

    .carousel-wrap {
      position: relative;
      background: rgba(255, 255, 255, 0.68);
      border: 1px solid rgba(45, 106, 79, 0.12);
      border-radius: var(--radius-lg);
      padding: 22px;
      box-shadow: var(--shadow);
      overflow: hidden;
    }

    .carousel-track {
      display: grid;
      grid-auto-flow: column;
      grid-auto-columns: calc(25% - 12px);
      gap: 16px;
      overflow-x: auto;
      scroll-behavior: smooth;
      scrollbar-width: none;
      padding-bottom: 2px;
    }

    .carousel-track::-webkit-scrollbar { display: none; }

    .product-card {
      background: var(--card);
      border-radius: var(--radius-md);
      border: 1px solid rgba(45, 106, 79, 0.12);
      overflow: hidden;
      box-shadow: 0 8px 16px rgba(26, 44, 34, 0.08);
      min-width: 0;
    }

    .product-card img {
      width: 100%;
      height: 145px;
      object-fit: cover;
      display: block;
    }

    .product-content { padding: 12px 13px 14px; }

    .product-name {
      font-weight: 800;
      font-size: .98rem;
      margin-bottom: 4px;
      color: var(--green-700);
    }

    .product-desc {
      color: var(--muted);
      font-size: .88rem;
      margin-bottom: 8px;
      min-height: 40px;
    }

    .price {
      font-weight: 800;
      color: var(--terracotta);
      font-family: 'Nunito', sans-serif;
      font-size: 1.02rem;
    }

    .carousel-controls {
      display: flex;
      gap: 8px;
    }

    .arrow-btn {
      width: 44px;
      height: 44px;
      border-radius: 999px;
      border: 1px solid rgba(45, 106, 79, 0.3);
      background: #fff;
      color: var(--green-700);
      font-size: 1.2rem;
      cursor: pointer;
      display: grid;
      place-items: center;
      transition: transform .2s ease, background .2s ease;
    }

    .arrow-btn:hover,
    .arrow-btn:focus-visible {
      transform: translateY(-1px);
      background: #f3fbf6;
      outline: none;
    }

    .seasonal-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 16px;
    }

    .season-card {
      background: #fff;
      border-radius: var(--radius-md);
      border: 1px solid rgba(45, 106, 79, 0.12);
      overflow: hidden;
      box-shadow: 0 8px 16px rgba(26, 44, 34, 0.08);
    }

    .season-card img { width: 100%; height: 190px; object-fit: cover; display: block; }
    .season-card .txt { padding: 14px; }
    .season-card h3 { font-size: 1.1rem; color: var(--green-700); margin-bottom: 4px; }
    .season-card p { margin: 0; color: var(--muted); font-size: .94rem; }

    .categories-grid {
      display: grid;
      grid-template-columns: repeat(5, minmax(0, 1fr));
      gap: 14px;
    }

    .category-card {
      position: relative;
      border-radius: var(--radius-md);
      overflow: hidden;
      min-height: 180px;
      box-shadow: var(--shadow);
      transition: transform .25s ease;
      isolation: isolate;
    }

    .category-card img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      display: block;
    }

    .category-overlay {
      position: absolute;
      inset: 0;
      background: linear-gradient(180deg, rgba(0,0,0,0.08) 10%, rgba(31, 81, 59, 0.72) 100%);
      color: #fff;
      display: flex;
      align-items: flex-end;
      padding: 14px;
      font-weight: 800;
      font-family: 'Nunito', sans-serif;
      font-size: 1.08rem;
      transition: background .25s ease;
    }

    .category-card:hover,
    .category-card:focus-within {
      transform: scale(1.04);
    }

    .category-card:hover .category-overlay,
    .category-card:focus-within .category-overlay {
      background: linear-gradient(180deg, rgba(0,0,0,0.16) 10%, rgba(31, 81, 59, 0.86) 100%);
    }

    .store-locator {
      background: #fff;
      border-radius: var(--radius-lg);
      border: 1px solid rgba(45, 106, 79, 0.13);
      box-shadow: var(--shadow);
      padding: 24px;
    }

    .store-search {
      display: flex;
      gap: 10px;
      flex-wrap: wrap;
      margin-top: 16px;
    }

    .input {
      flex: 1;
      min-width: 220px;
      border: 1px solid rgba(45, 106, 79, 0.3);
      border-radius: 12px;
      padding: 0 14px;
      min-height: 46px;
      font-size: 1rem;
    }

    .input:focus-visible {
      outline: 3px solid rgba(45, 106, 79, 0.24);
      outline-offset: 1px;
    }

    .store-results {
      margin-top: 16px;
      display: grid;
      gap: 12px;
    }

    .store-card {
      background: #f8fcf9;
      border: 1px solid rgba(45, 106, 79, 0.2);
      border-radius: var(--radius-sm);
      padding: 14px;
    }

    .store-card h4 { font-size: 1.02rem; color: var(--green-700); margin-bottom: 3px; }
    .store-meta { color: var(--muted); font-size: .92rem; margin-bottom: 2px; }
    .distance { color: var(--terracotta); font-weight: 700; font-size: .9rem; }

    .newsletter {
      background: linear-gradient(135deg, #fff 0%, #fff8e9 100%);
      border: 1px solid rgba(244, 162, 97, 0.36);
      border-radius: var(--radius-lg);
      padding: 28px;
      box-shadow: var(--shadow);
      text-align: center;
    }

    .newsletter h2 { color: var(--green-700); margin-bottom: 10px; }
    .newsletter p { color: var(--muted); margin: 0 auto 16px; max-width: 62ch; }

    .newsletter-form {
      display: flex;
      justify-content: center;
      gap: 10px;
      flex-wrap: wrap;
    }

    .message {
      margin-top: 12px;
      min-height: 1.2em;
      font-weight: 600;
      color: var(--green);
    }

    .footer {
      margin-top: 76px;
      background: #1f513b;
      color: #eaf4ef;
      padding: 44px 0 26px;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 20px;
      margin-bottom: 24px;
    }

    .footer h4 { font-size: 1rem; margin-bottom: 10px; }

    .footer a {
      display: block;
      color: #d5ebdf;
      text-decoration: none;
      margin: 4px 0;
      font-size: .93rem;
    }

    .footer a:hover,
    .footer a:focus-visible { color: #fff; outline: none; }

    .tagline {
      border-top: 1px solid rgba(234, 244, 239, 0.25);
      padding-top: 18px;
      font-size: .9rem;
      color: #d5ebdf;
      text-align: center;
    }

    @media (max-width: 1024px) {
      .hero-grid { grid-template-columns: 1fr; }
      .stats-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
      .carousel-track { grid-auto-columns: calc(33.333% - 11px); }
      .categories-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
      .seasonal-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    }

    @media (max-width: 700px) {
      .section { padding: 56px 0; }
      .header-inner { min-height: 70px; }
      .nav { gap: 0; }
      .nav a { padding: .45rem .65rem; font-size: .93rem; }
      .carousel-track { grid-auto-columns: calc(75% - 8px); }
      .categories-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
      .seasonal-grid, .footer-grid { grid-template-columns: 1fr; }
      .stats-grid { grid-template-columns: 1fr; }
      .hero-actions .btn { width: 100%; }
      .store-search .btn { width: 100%; }
    }
  </style>
</head>
<body>
  <header class="header">
    <div class="container header-inner">
      <a href="#home" class="brand" aria-label="Fresh Pantry home">
        <span class="brand-badge" aria-hidden="true">🥬</span>
        <span>Fresh Pantry</span>
      </a>
      <nav class="nav" aria-label="Header navigation">
        <a href="#featured-products">Products</a>
        <a href="#store-locator">Our Stores</a>
        <a href="#seasonal-picks">Recipes</a>
        <a href="#about">About Us</a>
      </nav>
    </div>
  </header>

  <main id="home">
    <section class="hero">
      <div class="container hero-grid">
        <div>
          <span class="eyebrow">Neighborhood Grocer, Reimagined</span>
          <h1>Discover Everyday Deliciousness</h1>
          <p>Unique flavors, quality ingredients, and unbeatable prices — all waiting for you at your neighborhood Fresh Pantry.</p>
          <div class="hero-actions">
            <button class="btn btn-primary" onclick="document.getElementById('store-locator').scrollIntoView({behavior:'smooth'})">Find a Store Near You</button>
            <button class="btn btn-secondary" onclick="document.getElementById('featured-products').scrollIntoView({behavior:'smooth'})">Explore This Week's Picks</button>
          </div>
        </div>
        <div class="hero-media" aria-hidden="true">
          <img src="https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&w=1200&q=80" alt="Colorful produce and pantry shelves">
          <div class="hero-chip">Fresh Finds This Week ✨</div>
        </div>
      </div>
    </section>

    <section class="container section" aria-label="Brand highlights">
      <div class="stats-banner">
        <div class="stats-grid">
          <div class="stat"><strong>500+</strong><span>Stores Nationwide</span></div>
          <div class="stat"><strong>4,000+</strong><span>Unique Products</span></div>
          <div class="stat"><strong>80%</strong><span>Private Label Items</span></div>
          <div class="stat"><strong>New Weekly</strong><span>Items Every Week</span></div>
        </div>
      </div>
    </section>

    <section class="section" id="featured-products">
      <div class="container">
        <div class="section-head">
          <div>
            <h2>Featured Products</h2>
            <p>Staff-favorite picks you’ll want in your cart this week.</p>
          </div>
          <div class="carousel-controls" aria-label="Featured products controls">
            <button class="arrow-btn" id="carouselPrev" aria-label="Show previous products">←</button>
            <button class="arrow-btn" id="carouselNext" aria-label="Show more products">→</button>
          </div>
        </div>

        <div class="carousel-wrap">
          <div class="carousel-track" id="productCarousel" tabindex="0" aria-label="Featured products carousel">
            <article class="product-card">
              <img src="https://images.unsplash.com/photo-1515003197210-e0cd71810b5f?auto=format&fit=crop&w=800&q=80" alt="Organic Maple Granola">
              <div class="product-content">
                <div class="product-name">Organic Maple Granola</div>
                <div class="product-desc">Crunchy oats, toasted nuts, and rich maple sweetness.</div>
                <div class="price">$4.99</div>
              </div>
            </article>
            <article class="product-card">
              <img src="https://images.unsplash.com/photo-1596040033229-a9821ebd058d?auto=format&fit=crop&w=800&q=80" alt="Everything But The Bagel Seasoning">
              <div class="product-content">
                <div class="product-name">Everything But The Bagel Seasoning</div>
                <div class="product-desc">Savory sesame-garlic blend that levels up any meal.</div>
                <div class="price">$2.49</div>
              </div>
            </article>
            <article class="product-card">
              <img src="https://images.unsplash.com/photo-1511381939415-e44015466834?auto=format&fit=crop&w=800&q=80" alt="Dark Chocolate Peanut Butter Cups">
              <div class="product-content">
                <div class="product-name">Dark Chocolate Peanut Butter Cups</div>
                <div class="product-desc">Creamy peanut butter wrapped in bold dark chocolate.</div>
                <div class="price">$3.79</div>
              </div>
            </article>
            <article class="product-card">
              <img src="https://images.unsplash.com/photo-1611270634834-36f8f2f0c1b9?auto=format&fit=crop&w=800&q=80" alt="Cauliflower Gnocchi">
              <div class="product-content">
                <div class="product-name">Cauliflower Gnocchi</div>
                <div class="product-desc">Soft, pillowy bites ready for your favorite sauce.</div>
                <div class="price">$2.99</div>
              </div>
            </article>
            <article class="product-card">
              <img src="https://images.unsplash.com/photo-1601315488950-3b5047998b38?auto=format&fit=crop&w=800&q=80" alt="Mandarin Orange Chicken">
              <div class="product-content">
                <div class="product-name">Mandarin Orange Chicken</div>
                <div class="product-desc">Crispy chicken with tangy citrus glaze, freezer-ready.</div>
                <div class="price">$5.49</div>
              </div>
            </article>
          </div>
        </div>
      </div>
    </section>

    <section class="section" id="seasonal-picks">
      <div class="container">
        <div class="section-head">
          <div>
            <h2>Seasonal Picks</h2>
            <p>Fresh combinations inspired by what’s tasting best right now.</p>
          </div>
        </div>
        <div class="seasonal-grid">
          <article class="season-card">
            <img src="https://images.unsplash.com/photo-1467003909585-2f8a72700288?auto=format&fit=crop&w=1200&q=80" alt="Spring produce and herbs">
            <div class="txt">
              <h3>Farmer’s Market Favorites</h3>
              <p>Crisp greens, bright herbs, and peak-season produce bundles.</p>
            </div>
          </article>
          <article class="season-card">
            <img src="https://images.unsplash.com/photo-1505253758473-96b7015fcd40?auto=format&fit=crop&w=1200&q=80" alt="Colorful smoothie ingredients">
            <div class="txt">
              <h3>Blend & Boost</h3>
              <p>Smoothie staples packed with flavor and feel-good ingredients.</p>
            </div>
          </article>
          <article class="season-card">
            <img src="https://images.unsplash.com/photo-1473093295043-cdd812d0e601?auto=format&fit=crop&w=1200&q=80" alt="Prepared meal with fresh ingredients">
            <div class="txt">
              <h3>Weeknight Wonders</h3>
              <p>Easy, satisfying dinners with globally inspired pantry twists.</p>
            </div>
          </article>
        </div>
      </div>
    </section>

    <section class="section" id="about">
      <div class="container">
        <div class="section-head">
          <div>
            <h2>Shop by Category</h2>
            <p>Browse beloved staples and exciting discoveries by aisle.</p>
          </div>
        </div>
        <div class="categories-grid" aria-label="Product categories">
          <a href="#" class="category-card" aria-label="Snacks and Sweets">
            <img src="https://images.unsplash.com/photo-1481391032119-d89fee407e44?auto=format&fit=crop&w=900&q=80" alt="Snacks and sweets">
            <div class="category-overlay">Snacks &amp; Sweets</div>
          </a>
          <a href="#" class="category-card" aria-label="Fresh Produce">
            <img src="https://images.unsplash.com/photo-1610832958506-aa56368176cf?auto=format&fit=crop&w=900&q=80" alt="Fresh produce">
            <div class="category-overlay">Fresh Produce</div>
          </a>
          <a href="#" class="category-card" aria-label="Frozen Favorites">
            <img src="https://images.unsplash.com/photo-1488459716781-31db52582fe9?auto=format&fit=crop&w=900&q=80" alt="Frozen favorites">
            <div class="category-overlay">Frozen Favorites</div>
          </a>
          <a href="#" class="category-card" aria-label="Beverages">
            <img src="https://images.unsplash.com/photo-1497534446932-c925b458314e?auto=format&fit=crop&w=900&q=80" alt="Beverages">
            <div class="category-overlay">Beverages</div>
          </a>
          <a href="#" class="category-card" aria-label="Dairy and Cheese">
            <img src="https://images.unsplash.com/photo-1559598467-f8b76c8155d0?auto=format&fit=crop&w=900&q=80" alt="Dairy and cheese">
            <div class="category-overlay">Dairy &amp; Cheese</div>
          </a>
        </div>
      </div>
    </section>

    <section class="section" id="store-locator">
      <div class="container">
        <div class="store-locator">
          <h2>Find Your Fresh Pantry</h2>
          <p>Enter your zip code to discover the nearest store, hours, and directions.</p>
