  <script>
    const carousel = document.getElementById('productCarousel');
    const prevBtn = document.getElementById('carouselPrev');
    const nextBtn = document.getElementById('carouselNext');

    function getScrollAmount() {
      const card = carousel.querySelector('.product-card');
      return card ? card.getBoundingClientRect().width + 16 : 280;
    }

    prevBtn.addEventListener('click', () => {
      carousel.scrollBy({ left: -getScrollAmount(), behavior: 'smooth' });
    });

    nextBtn.addEventListener('click', () => {
      carousel.scrollBy({ left: getScrollAmount(), behavior: 'smooth' });
    });

    const storeData = [
      {
        name: 'Fresh Pantry — Lincoln Park',
        address: '2140 N. Halsted St, Chicago, IL 60614',
        hours: '8am – 9pm Daily',
        distance: '0.8 mi'
      },
      {
        name: 'Fresh Pantry — Wicker Park',
        address: '1840 W. North Ave, Chicago, IL 60622',
        hours: '8am – 9pm Daily',
        distance: '1.4 mi'
      },
      {
        name: 'Fresh Pantry — Lakeview',
        address: '3745 N. Lincoln Ave, Chicago, IL 60613',
        hours: '8am – 9pm Daily',
        distance: '2.1 mi'
      }
    ];

    const storeForm = document.getElementById('storeSearchForm');
    const zipInput = document.getElementById('zipInput');
    const storeResults = document.getElementById('storeResults');

    storeForm.addEventListener('submit', (event) => {
      event.preventDefault();
      const zip = zipInput.value.trim();

      if (!/^\d{5}$/.test(zip)) {
        storeResults.innerHTML = '<div class="store-card" role="alert"><h4>Please enter a valid 5-digit zip code.</h4></div>';
        return;
      }

      storeResults.innerHTML = storeData.map((store) => `
        <article class="store-card">
          <h4>${store.name}</h4>
          <div class="store-meta">${store.address}</div>
          <div class="store-meta">${store.hours}</div>
          <div class="distance">${store.distance}</div>
        </article>
      `).join('');
    });

    const newsletterForm = document.getElementById('newsletterForm');
    const newsletterMessage = document.getElementById('newsletterMessage');
    const emailInput = document.getElementById('emailInput');

    newsletterForm.addEventListener('submit', (event) => {
      event.preventDefault();
      if (!emailInput.checkValidity()) {
        newsletterMessage.textContent = 'Please enter a valid email address.';
        return;
      }
      newsletterMessage.textContent = 'Thanks for subscribing! Check your inbox for a welcome treat.';
      newsletterForm.reset();
    });
  </script>
